// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 t) public {
        vm.assume(actor != address(0));
        vm.assume(t < block.timestamp); // a past unlock time is admissible input
        amount = bound(amount, 0, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        (uint unlockTime, ) = c.Acc(actor);
        // unlockTime stored must be exactly max(t, now) = now here
        assertTrue(unlockTime == (t > block.timestamp ? t : block.timestamp));
    }
}
